session_protocol.implementation:
extern crate litex;
use std::io::{self, BufRead};
fn main() {
    let mut rt=litex::runtime::Runtime::new(litex::launch_command::LaunchCommand::Eval {code:String::new(),session:true,strict:true,language:litex::launch_command::OutputLanguage::English});
    let mut code=String::new();let mut n=0;
    for line in io::stdin().lock().lines() {
        let line=line.unwrap();if line=="===QUIT===" {break;}
        if line!="===END===" {code.push_str(&line);code.push('\n');continue;}
        n+=1;let run=rt.run_litex_code(&code).unwrap();
        let prefix=format!("tmp/2026-10-03/f-authoring-repairs/frame-{:03}",n);
        std::fs::write(format!("{}.lit",prefix),&code).unwrap();
        std::fs::write(format!("{}-normal.json",prefix),litex::json_output::emit_run_normal(&run,&rt,"F authoring session",None)).unwrap();
        std::fs::write(format!("{}-detailed.json",prefix),litex::json_output::emit_run_detailed(&run,&rt,"F authoring session",None)).unwrap();
        println!("FRAME {} success={} session_error={:?} env_depth={}",n,run.success,run.session_error,rt.execution_environments_stack.len());
        code.clear();
    }
}

