# Cases use discarded sketch scopes; no cross-case facts.

# P01: intersect({1, 2}, {2, 3}) = {2}
sketch:
    by extension:
        ? intersect({1, 2}, {2, 3}) = {2}
        claim:
            ? forall x intersect({1, 2}, {2, 3}):
                x $in {2}
            x $in {1, 2}
            x $in {2, 3}
            x = 1 or x = 2
            by cases:
                ? x $in {2}
                case x = 1:
                    1 $in {2, 3}
                    impossible 1 $in {2, 3}
                case x = 2:
                    x $in {2}
        forall x {2}:
            x $in intersect({1, 2}, {2, 3})

# P02: intersect({}, {1}) = {}
sketch:
    intersect({}, {1}) = {}

